draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // bed
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.rect(50, H/2, W-100, 100);
  ctx.stroke();

  // person
  ctx.beginPath();
  ctx.arc(150, H/2-25+50*Math.sin(t), 25, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(150, H/2-25+50*Math.sin(t));
  ctx.lineTo(150, H/2+25+50*Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(150, H/2+50*Math.sin(t));
  ctx.lineTo(120, H/2+75*Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(150, H/2+50*Math.sin(t));
  ctx.lineTo(180, H/2+75*Math.sin(t));
  ctx.stroke();

  // dog
  ctx.beginPath();
  ctx.arc(W-150, H/2-50+25*Math.sin(t), 25, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W-150, H/2-50+25*Math.sin(t));
  ctx.lineTo(W-150, H/2-25+25*Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W-150, H/2-25+25*Math.sin(t));
  ctx.lineTo(W-120, H/2-50+25*Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W-150, H/2-25+25*Math.sin(t));
  ctx.lineTo(W-180, H/2-50+25*Math.sin(t));
  ctx.stroke();

  // dog pulling person
  ctx.beginPath();
  ctx.moveTo(150, H/2+25+50*Math.sin(t));
  ctx.lineTo(W-150, H/2-25+25*Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
